INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 14, 'theory', 'Quiz: HTML — Images, Media and Tables');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 14, 0, 'What should you write in alt for a picture that only decorates the page?', '["The word \"picture\"", "An empty string: the attribute stays, but the value is empty", "The file name", "The alt attribute should be removed entirely"]', 1, 'An empty alt tells a screen reader to skip the picture. If there is no attribute at all, many programs read the file name aloud, and a validator reports an error.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 14, 1, 'Why put width and height attributes with the real file dimensions on an img?', '["So the browser stretches the picture to those dimensions", "So the file loads faster", "So the tag counts as valid", "So the browser computes the proportions in advance and reserves space, and the layout does not jump"]', 3, 'From width and height the browser gets the aspect ratio before the file loads and leaves room for the picture. Without them the content below shifts, and the CLS metric grows. The real size on screen is then set by styles.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 14, 2, 'What role does sizes play next to srcset?', '["It tells the browser how wide the picture will be in the layout, so it can pick a suitable file", "It limits the file size in kilobytes", "It changes the displayed size of the picture", "It chooses the file format: avif or webp"]', 0, 'srcset lists the files and their widths in pixels, sizes describes the slot in the layout. Knowing the slot, the screen density and the network, the browser picks the file itself. The displayed width is still set by CSS, and the format is chosen by the picture tag.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 14, 3, 'What does the scope="col" attribute give a table header cell?', '["It colors the table header", "It merges all the cells of the column", "It ties the header to the column: a screen reader reads a number together with the column name", "It hides the header from screen readers"]', 2, 'scope says what the header relates to: col to a column, row to a row. So on a cell with a value, a screen reader announces both the value and its headers. Cells are merged by colspan and rowspan, and appearance is handled by CSS.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 14, 4, 'How does an iframe with a sandbox attribute with no values behave?', '["It allows everything, like an ordinary frame", "It forbids scripts, forms and navigation inside the frame; needed abilities are allowed one at a time", "It changes nothing: sandbox requires a list of values", "It postpones loading the frame until scrolling"]', 1, 'An empty sandbox turns on the strictest mode, and values like allow-scripts or allow-forms give back individual rights one by one. Lazy loading is turned on by loading=lazy, and the name for a screen reader is set by title.');
